    $showValues=function($values,$options=[]){
        $values=is_array($values)?$values:[$values];
        return collect($values)->filter(fn($v)=>$v!==null&&$v!=='')->map(function($value)use($options){
            if((string)$value==='true')return 'Verdadero';if((string)$value==='false')return 'Falso';
            return $options[$value]??$value;
        })->join(', ')?:'Sin respuesta';
    };
